"""Real JEE Main questions — Physics Unit 3: Laws of Motion. Our own solutions; chk re-solves each one — equilibrium
by resolving forces, connected bodies by solving the simultaneous Newton equations (Cramer), motion under forces by
stepping in time. Skipped: items with inconsistent data (a work/power item whose stated path needs an unstated
initial velocity, a moving-wedge item whose key ignores the block–wedge coupling, an incline item that does not say
the block slides uniformly) and a graph item whose options look alike in the scan."""
import math
from common import new_registry, pick, near, verify
P, add = new_registry()
def solve2(a, b, c, d, e, f):   # a x + b y = e ; c x + d y = f
    D = a * d - b * c; return (e * d - b * f) / D, (a * f - e * c) / D
def step(F, m, T, v0=(0, 0, 0), dt=1e-4):   # integrate a = F(t)/m
    v = list(v0); r = [0, 0, 0]; t = 0.0
    while t < T - 1e-12:
        f = F(t + dt / 2); a = [x / m for x in f]
        r = [ri + (vi + ai * dt / 2) * dt for ri, vi, ai in zip(r, v, a)]; v = [vi + ai * dt for vi, ai in zip(v, a)]; t += dt
    return v, r

