add(('2024', 'Apr', '2024-04-06', 2), 'pulley', 'A body of weight 200 N is suspended form a tree branch thought a chain of mass 10 kg. The branch pulls the chain by a force equal to (if g = 10 m/s^{2}):', ['150 N', '300 N', '200 N', '100 N'], 2, lambda: pick([150, 300, 200, 100], 200 + 10 * 10),
    ['Chain + body in equilibrium: branch force = 200 + 100 = 300 N.'], 'pulley', 1)
add(('2024', 'Apr', '2024-04-06', 1), 'pulley', 'A light string passing over a smooth light pulley connects two blocks of masses m_{1} and m_{2} (where m_{2} > m_{1}). If the acceleration of the system is \\f{g}{√{2}}, then the ratio of the masses \\f{m_{1}}{m_{2}} is :', ['\\f{√{2} − 1}{√{2} + 1}', '\\f{1 + √{5}}{√{5} − 1}', '\\f{1 + √{5}}{√{2} − 1}', '\\f{√{3} + 1}{√{2} − 1}'], 1,
    lambda: (lambda r: near([(math.sqrt(2) - 1) / (math.sqrt(2) + 1), 2.6, 7.8, 6.6], r))((1 - 1 / math.sqrt(2)) / (1 + 1 / math.sqrt(2))), ['a = \\f{(m_{2} − m_{1})g}{m_{1} + m_{2}} = \\f{g}{√{2}}; with r = m_{1}/m_{2}: \\f{1 − r}{1 + r} = \\f{1}{√{2}} → r = \\f{√{2} − 1}{√{2} + 1}.'], 'pulley', 2)
add(('2024', 'Apr', '2024-04-09', 2), 'pulley', 'A 1 kg mass is suspended from the ceiling by a rope of length 4 m. A horizontal force \'F\' is applied at the mid point of the rope so that the rope makes an angle of 45° with respect to the vertical axis. The magnitude of F is :', ['\\f{10}{√{2}} N', '1 N', '\\f{1}{10 × √{2}} N', '10 N'], 4,
    lambda: near([10 / math.sqrt(2), 1, 1 / (10 * math.sqrt(2)), 10], 1 * 10 * math.tan(math.radians(45))), ['At the midpoint: lower rope pulls down with mg = 10 N, F pulls sideways, upper rope at 45° balances both.', 'tan45° = \\f{F}{mg} → F = 10 N.'], 'pulley', 1)
add(('2024', 'Apr', '2024-04-09', 1), 'pulley', 'A light unstretchable string passing over a smooth light pulley connects two blocks of masses m_{1} and m_{2}. If the acceleration of the system is \\f{g}{8}, then the ratio of the masses \\f{m_{2}}{m_{1}} is:', ['9 : 7', '4 : 3', '5 : 3', '8 : 1'], 1,
    lambda: near([9 / 7, 4 / 3, 5 / 3, 8], (1 + 1 / 8) / (1 - 1 / 8)), ['\\f{m_{2} − m_{1}}{m_{2} + m_{1}} = \\f{1}{8} → \\f{m_{2}}{m_{1}} = \\f{9}{7}.'], 'pulley', 1)
add(('2026', 'Apr', '2026-04-02', 2), 'pulley', 'Two blocks of masses 2 kg and 1 kg respectively, are tied to the ends of a string which passes over a light frictionless pulley. The masses are held at rest at the same horizontal level and then released. The distance traversed by the centre of mass in 2 s is ____ m. (Take g = 10 m/s^{2})',
    ['3.33', '3.12', '2.22', '1.42'], 3, lambda: (lambda a: near([3.33, 3.12, 2.22, 1.42], 0.5 * ((2 * a - 1 * a) / 3) * 4))((2 - 1) * 10 / 3), ['a = \\f{(2 − 1)g}{3} = \\f{10}{3} m s^{−2}; 2 kg goes down, 1 kg up.', 'a_{cm} = \\f{2a − a}{3} = \\f{10}{9} → s = ½ × \\f{10}{9} × 4 ≈ 2.22 m.'], 'pulley', 2)
add(('2024', 'Jan', '2024-01-30', 1), 'pulley', 'All surfaces shown in figure are assumed to be frictionless and the pulleys and the string are light. A 2 kg block on a 30° incline is tied by a string that runs over a fixed pulley and down to a movable pulley carrying a 4 kg block (string fixed to the ceiling on the other side). The acceleration of the block of mass 2 kg is :',
    ['g', '\\f{g}{3}', '\\f{g}{2}', '\\f{g}{4}'], 2, lambda: (lambda Ta: near([10, 10 / 3, 5, 2.5], Ta[1]))(solve2(1, -2, 2, 2, 2 * 10 * 0.5, 4 * 10)),   # T − 2a1 = 10 ; 2T + 2a1 = 40
    ['Constraint: the 2 kg block moves twice as far as the 4 kg block (a_{1} = 2a_{2}).', '2 kg: T − 2g sin30° = 2a_{1}; 4 kg: 4g − 2T = 4a_{2} = 2a_{1} → 40 − 20 − 4a_{1} = 2a_{1} → a_{1} = \\f{10}{3} = \\f{g}{3}.'], 'pulley', 3)
add(('2024', 'Jan', '2024-01-30', 2), 'pulley', 'Three blocks A (5 kg), B (3 kg) and C (2 kg) are pulled on a horizontal smooth surface by a force of 80 N applied on C (strings T_{1} between A and B, T_{2} between B and C). The tensions T_{1} and T_{2} in the string are respectively:', ['40 N, 64 N', '60 N, 80 N', '88 N, 96 N', '80 N, 100 N'], 1,
    lambda: (lambda a: pick(['40 N, 64 N', '60 N, 80 N', '88 N, 96 N', '80 N, 100 N'], f'{round(5 * a)} N, {round(8 * a)} N'))(80 / 10), ['a = \\f{80}{10} = 8 m s^{−2}. T_{1} pulls A: 5 × 8 = 40 N; T_{2} pulls A + B: 8 × 8 = 64 N.'], 'pulley', 1)
add(('2024', 'Jan', '2024-01-31', 2), 'pulley', 'A light string passing over a smooth light fixed pulley connects two blocks of masses m_{1} and m_{2}. If the acceleration of the system is g/8, then the ratio of masses is', ['\\f{9}{7}', '\\f{8}{1}', '\\f{4}{3}', '\\f{5}{3}'], 1,
    lambda: near([9 / 7, 8, 4 / 3, 5 / 3], (1 + 1 / 8) / (1 - 1 / 8)), ['\\f{m_{2} − m_{1}}{m_{1} + m_{2}} = \\f{1}{8} → \\f{m_{2}}{m_{1}} = \\f{9}{7}.'], 'pulley', 1)
add(('2026', 'Apr', '2026-04-05', 1), 'pulley', 'Three masses m_{1} = 4 kg, m_{2} = 4 kg and m_{3} = 6 kg are suspended from a fixed smooth frictionless pulley: m_{1} hangs on one side (string tension T_{1}); m_{2} hangs on the other side (tension T_{1}) with m_{3} hanging below m_{2} by a string of tension T_{2}. The value of T_{1}/T_{2} is ____ (take g = 10 m/s^{2})',
    ['5/3', '2/3', '3/5', '2/5'], 1, lambda: (lambda a: near([5 / 3, 2 / 3, 3 / 5, 2 / 5], (4 * (10 + a)) / (6 * (10 - a))))((10 - 4) * 10 / 14), ['a = \\f{(10 − 4)g}{14} = \\f{30}{7} m s^{−2}.', 'T_{1} = 4(g + a) = \\f{400}{7}; T_{2} = 6(g − a) = \\f{240}{7} → \\f{5}{3}.'], 'pulley', 2)
add(('2026', 'Jan', '2026-01-28', 2), 'pulley', 'A small block of mass m slides down from the top of a frictionless inclined surface (angle θ, base length L), while the inclined plane is moving towards left with constant acceleration a_{0}. Assuming that initially the small block is at the top of the inclined plane, the time it takes to reach the lowest point of the inclined plane is ____',
    ['√{\\f{2L}{g sinθ − a_{0}cosθ}}', '√{\\f{4L}{g sin2θ − a_{0}(1 + cos2θ)}}', '√{\\f{2L}{g sin2θ − a_{0}(1 + cos2θ)}}', '√{\\f{4L}{g cos^{2}θ − a_{0}sinθcosθ}}'], 2,
    lambda: (lambda th, a0, L: near([math.sqrt(2 * L / (10 * math.sin(th) - a0 * math.cos(th))), math.sqrt(4 * L / (10 * math.sin(2 * th) - a0 * (1 + math.cos(2 * th)))), math.sqrt(2 * L / (10 * math.sin(2 * th) - a0 * (1 + math.cos(2 * th)))), math.sqrt(4 * L / (10 * math.cos(th) ** 2 - a0 * math.sin(th) * math.cos(th)))],
                                          math.sqrt(2 * (L / math.cos(th)) / (10 * math.sin(th) - a0 * math.cos(th)))))(math.radians(50), 2.0, 3.0),
    ['In the wedge frame a pseudo-force ma_{0} acts to the right, i.e. partly UP the slope: a_{rel} = g sinθ − a_{0}cosθ.', 'Slope length \\f{L}{cosθ}: t = √{\\f{2L}{cosθ(g sinθ − a_{0}cosθ)}} = √{\\f{4L}{g sin2θ − a_{0}(1 + cos2θ)}}.'], 'pulley', 3)

# ---------------- dynamics of circular motion ----------------
add(('2024', 'Feb', '2024-02-01', 1), 'circd', 'A ball of mass 0.5 kg is attached to a string of length 50 cm. The ball is rotated on a horizontal circular path about its vertical axis. The maximum tension that the string can bear is 400 N. The maximum possible value of angular velocity of the ball in rad/s is:',
    ['1600', '40', '1000', '20'], 2, lambda: pick([1600, 40, 1000, 20], round(math.sqrt(400 / (0.5 * 0.5)), 9)), ['T = mω^{2}L → ω = √{\\f{400}{0.5 × 0.5}} = 40 rad/s.'], 'circd', 1)
add(('2024', 'Apr', '2024-04-06', 2), 'circd', 'A car of 800 kg is taking turn on a banked road of radius 300 m and angle of banking 30°. If coefficient of static friction is 0.2 then the maximum speed with which car can negotiate the turn safely : (g = 10 m/s^{2}, √{3} = 1.73)',
    ['70.4 m/s', '51.4 m/s', '264 m/s', '102.8 m/s'], 2, lambda: near([70.4, 51.4, 264, 102.8], math.sqrt(300 * 10 * (0.2 + 1 / 1.73) / (1 - 0.2 / 1.73))), ['v_{max}^{2} = rg\\f{μ + tanθ}{1 − μ tanθ} = 3000 × \\f{0.778}{0.884} → v ≈ 51.4 m/s.'], 'circd', 2)
add(('2024', 'Apr', '2024-04-08', 2), 'circd', 'A circular table is rotating with an angular velocity of ω rad/s about its axis. There is a smooth groove along a radial direction on the table. A steel ball is gently placed at a distance of 1 m on the groove. All the surface are smooth. If the radius of the table is 3 m, the radial velocity of the ball w.r.t. the table at the time ball leaves the table is x√{2}ω m/s, where the value of x is.',
    None, 2, lambda: (lambda w: round(math.sqrt(w * w * (9 - 1)) / (math.sqrt(2) * w)))(1.7), ['In the rotating frame only the centrifugal force acts along the groove: r̈ = ω^{2}r.', 'v_{r}^{2} = ω^{2}(r^{2} − r_{0}^{2}) = 8ω^{2} → v_{r} = 2√{2}ω → x = 2.'], 'circd', 3)
add(('2026', 'Apr', '2026-04-02', 2), 'circd', 'A 0.5 kg mass is in contact against the inner wall of a cylindrical drum of radius 4 m rotating about its vertical axis. The minimum rotational speed of the drum to enable the mass to remain stuck to the wall (without falling) is 5 rad/s. The coefficient of friction between the drum\'s inner wall surface and mass is ____ . (Take g = 10 m/s^{2})',
    ['0.1', '0.5', '0.7', '0.3'], 1, lambda: pick([0.1, 0.5, 0.7, 0.3], round(10 / (25 * 4), 9)), ['Wall pushes inward N = mω^{2}r; friction μN must hold mg.', 'μ = \\f{g}{ω^{2}r} = \\f{10}{25 × 4} = 0.1.'], 'circd', 2)
add(('2025', 'Jan', '2025-01-24', 1), 'circd', 'A car of mass \'m\' moves on a banked road having radius \'r\' and banking angle θ. To avoid slipping from banked road, the maximum permissible speed of the car is v_{0}. The coefficient of friction μ between the wheels of the car and the banked road is',
    ['μ = \\f{v_{0}^{2} − rg tanθ}{rg + v_{0}^{2} tanθ}', 'μ = \\f{v_{0}^{2} + rg tanθ}{rg − v_{0}^{2} tanθ}', 'μ = \\f{v_{0}^{2} − rg tanθ}{rg − v_{0}^{2} tanθ}', 'μ = \\f{v_{0}^{2} + rg tanθ}{rg + v_{0}^{2} tanθ}'], 1,
    lambda: (lambda r, th, mu: (lambda v2: near([(v2 - r * 10 * math.tan(th)) / (r * 10 + v2 * math.tan(th)), 9, 7, 5], mu))(r * 10 * (mu + math.tan(th)) / (1 - mu * math.tan(th))))(100, math.radians(20), 0.3),
    ['At v_{max}, friction acts down the slope: v_{0}^{2} = rg\\f{μ + tanθ}{1 − μ tanθ}.', 'Solve for μ: μ = \\f{v_{0}^{2} − rg tanθ}{rg + v_{0}^{2}tanθ}.'], 'circd', 2)
add(('2024', 'Jan', '2024-01-29', 2), 'circd', 'A stone of mass 900 g is tied to a string and moved in a vertical circle of radius 1 m making 10 rpm. The tension in the string, when the stone is at the lowest point is (if π^{2} = 9.8 and g = 9.8 m/s^{2})', ['97 N', '9.8 N', '8.82 N', '17.8 N'], 2,
    lambda: near([97, 9.8, 8.82, 17.8], 0.9 * (9.8 + (2 * math.pi * 10 / 60) ** 2 * 1 * 9.8 / math.pi ** 2)), ['ω = \\f{2π × 10}{60} = \\f{π}{3} → ω^{2}r = \\f{π^{2}}{9} = \\f{9.8}{9}.', 'T = m(g + ω^{2}r) = 0.9 × 9.8 × \\f{10}{9} = 9.8 N.'], 'circd', 2)
add(('2025', 'Jan', '2025-01-29', 1), 'circd', 'A body of mass \'m\' connected to a massless and unstretchable string goes in vertical circle of radius \'R\' under gravity g. The other end of the string is fixed at the center of circle. If velocity at top of circular path is n√{gR}, where, n ≥ 1, then ratio of kinetic energy of the body at bottom to that at top of the circle is',
    ['\\f{n + 4}{n}', '\\f{n^{2} + 4}{n^{2}}', '\\f{n}{n + 4}', '\\f{n^{2}}{n^{2} + 4}'], 2, lambda: (lambda n: near([(n + 4) / n, (n * n + 4) / (n * n), n / (n + 4), n * n / (n * n + 4)], (n * n + 4) / (n * n)))(1.7),
    ['v_{bottom}^{2} = v_{top}^{2} + 4gR = (n^{2} + 4)gR.', 'Ratio = \\f{n^{2} + 4}{n^{2}}.'], 'circd', 2)
add(('2024', 'Jan', '2024-01-31', 1), 'circd', 'A coin is placed on a disc. The coefficient of friction between the coin and the disc is μ. If the distance of the coin from the center of the disc is r, the maximum angular velocity which can be given to the disc, so that the coin does not slip away, is :',
    ['\\f{μg}{r}', '√{\\f{r}{μg}}', '√{\\f{μg}{r}}', '\\f{μ}{√{rg}}'], 3, lambda: (lambda mu, r: near([mu * 9.8 / r, math.sqrt(r / (mu * 9.8)), math.sqrt(mu * 9.8 / r), mu / math.sqrt(r * 9.8)], math.sqrt(mu * 9.8 / r)))(0.4, 0.2),
    ['Friction supplies the centripetal force: mω^{2}r ≤ μmg → ω_{max} = √{\\f{μg}{r}}.'], 'circd', 1)
add(('2025', 'Jan', '2025-01-22', 1), 'circd', 'A bob of mass m is suspended at a point O by a light string of length l and left to perform vertical motion (circular). Initially, by applying horizontal velocity v_{0} at the lowest point \'A\', the string becomes slack when the bob reaches the top point \'D\'. B is 60° from A and C is 60° from D (measured at O). The ratio of the kinetic energy of the bob at the points B and C is ____.',
    ['3', '2', '4', '1'], 2, lambda: (lambda vD2: pick([3, 2, 4, 1], round((vD2 + 2 * 10 * (2 - 0.5)) / (vD2 + 2 * 10 * (2 - 1.5)), 9)))(10 * 1), ['Slack exactly at the top → v_{D}^{2} = gl.', 'Heights above A: B = \\f{l}{2}, C = \\f{3l}{2}, D = 2l → v_{B}^{2} = gl + 3gl = 4gl, v_{C}^{2} = gl + gl = 2gl → ratio 2.'], 'circd', 2)
add(('2024', 'Jan', '2024-01-29', 2), 'circd', 'A bob of mass \'m\' is suspended by a light string of length \'L\'. It is imparted a minimum horizontal velocity at the lowest point A such that it just completes half circle reaching the top most position B. The ratio of kinetic energies \\f{(K.E.)_{A}}{(K.E.)_{B}} is :', ['3 : 2', '5 : 1', '2 : 5', '1 : 5'], 2,
    lambda: pick(['3 : 2', '5 : 1', '2 : 5', '1 : 5'], f'{round((1 + 4) / 1)} : 1'), ['Just completing: v_{B}^{2} = gL at the top; v_{A}^{2} = gL + 4gL = 5gL.', 'KE ratio 5 : 1.'], 'circd', 1)
for _p in P: _p['t'] = _p['fam']
